    Bug 1921394 - Clean up leaked objects in FolderDatabase. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D230620

diff --git a/mailnews/db/panorama/src/FolderDatabase.cpp b/mailnews/db/panorama/src/FolderDatabase.cpp
index f171da9077c..564fa5e4ae2 100644
--- a/mailnews/db/panorama/src/FolderDatabase.cpp
+++ b/mailnews/db/panorama/src/FolderDatabase.cpp
@@ -52,12 +52,22 @@ FolderDatabase::Observe(nsISupports* aSubject, const char* aTopic,
   }
   sStatements.Clear();

-  sFoldersById.Clear();
-
   if (sConnection) {
     sConnection->Close();
+    sConnection = nullptr;
+  }
+
+  // Break the reference cycles. This is much tidier than using the cycle
+  // collection macros, especially as Folder is declared threadsafe.
+  for (auto iter = sFoldersById.Iter(); !iter.Done(); iter.Next()) {
+    iter.UserData()->mRoot = nullptr;
+    iter.UserData()->mParent = nullptr;
+    iter.UserData()->mChildren.Clear();
   }

+  sFoldersById.Clear();
+  sFoldersByPath.Clear();
+
   nsCOMPtr<nsIObserverService> obs = mozilla::services::GetObserverService();
   obs->RemoveObserver(this, "profile-before-change");
